#!/usr/bin/env bash
# Regenerate env/requirements.lock.txt and env/pip-freeze.p0.txt from a freshly *resolved* build.
# Only needed when node-pack commits or their requirements change on purpose. Normal rebuilds use the lock.
#   1. temporarily build with the resolver path (see git history of env/Containerfile before the lock), tag :resolve
#   2. bash env/lock_deps.sh localhost/sonoranlab-comfy:resolve
set -euo pipefail
cd "$(dirname "$0")"
IMG=${1:?image built with the resolver}
BASE=$(sed -n 's/^ARG BASE=//p' Containerfile)
tmp=$(mktemp -d); trap 'rm -rf "$tmp"' EXIT
podman run --rm --network=none "$BASE" pip freeze > "$tmp/base.txt"
podman run --rm --network=none "$IMG" pip freeze > "$tmp/final.txt"
comm -13 <(sort "$tmp/base.txt") <(sort "$tmp/final.txt") > "$tmp/delta.txt"
podman run --rm -v "$tmp:/s:Z" "$BASE" pip install -q --dry-run --ignore-installed --no-deps --report /s/report.json -r /s/delta.txt
python3 - "$tmp/report.json" > requirements.lock.txt <<'PY'
import json, sys
r = json.load(open(sys.argv[1]))
print("# Exact pip layer that env/Containerfile adds on top of the pinned toolbox digest (generated by env/lock_deps.sh).")
print("# Installed with --require-hashes --no-deps: nothing outside this list can be pulled in or upgraded.\n")
for it in sorted(r["install"], key=lambda i: i["metadata"]["name"].lower()):
    m, a = it["metadata"], it["download_info"]["archive_info"]
    print(f"{m['name']}=={m['version']} \\\n    --hash=sha256:{a.get('hashes', {}).get('sha256') or a['hash'].split('=')[-1]}")
PY
cp "$tmp/final.txt" pip-freeze.p0.txt
echo "lock: $(grep -c -- '--hash' requirements.lock.txt) packages; freeze: $(wc -l < pip-freeze.p0.txt) lines"
